  .update((p, dt) => {
    if (Math.abs(length(toCenter(p)) - 100) > 60) { p.kill(); }
  })
  .emitter("ring", { x: 250, y: 150, maxRate: 5 })
    .rate((t, live) => (live < 50 ? 5 : 0))
    .spawn((p, rng) => {
      p.vel = vec2(0, -Math.sqrt(500 / 100) * (1 + 0.1 * rng()));
      p.life = 30;
    });

